import{e as t,ab as a,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const c=JSON.parse('{"title":"Monthly Updates [June]","description":"June 2025 updates","frontmatter":{"title":"Monthly Updates [June]","description":"June 2025 updates","date":"2025-06-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/june-2025.md","filePath":"posts/june-2025.md"}'),l={name:"posts/june-2025.md"};function d(h,e,p,f,m,g){const r=a("Post");return o(),n("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>All guides written by Dan, like <strong><a href="https://rentry.co/coffeeguide" target="_blank" rel="noreferrer">/coffee/</a></strong> &amp; <strong><a href="https://rentry.co/poolguide" target="_blank" rel="noreferrer">/pool/</a></strong>, have been compiled in <strong><a href="https://rentry.co/danfmhy/" target="_blank" rel="noreferrer">/danfmhy/</a></strong>.</p></li><li><p>You can now search FMHY using <a href="https://github.com/fmhy/bookmarks?tab=readme-ov-file#goggle" target="_blank" rel="noreferrer">Brave Goggles</a>.</p></li><li><p>Added <a href="https://fmhy.net/gaming#nintendo-roms" target="_blank" rel="noreferrer">Nintendo</a>, <a href="https://fmhy.net/gaming#sony-roms" target="_blank" rel="noreferrer">Sony</a>, and <a href="https://fmhy.net/gaming#rom-resources" target="_blank" rel="noreferrer">Resource</a> sections to ROMs.</p></li><li><p>Added <a href="https://fmhy.net/gaming#rubiks-cube" target="_blank" rel="noreferrer">Rubik&#39;s Cube</a>, <a href="https://fmhy.net/gaming#minesweeper" target="_blank" rel="noreferrer">Minesweeper</a>, and <a href="https://fmhy.net/gaming#crossword-puzzles" target="_blank" rel="noreferrer">Crossword</a> sections to Puzzles.</p></li><li><p>Added a <a href="https://fmhy.net/educational#game-learning" target="_blank" rel="noreferrer">Game Learning</a> section to Educational, with <a href="https://fmhy.net/educational#rubiks-cube" target="_blank" rel="noreferrer">Rubik&#39;s Cube</a> + <a href="https://fmhy.net/educational#chess" target="_blank" rel="noreferrer">Chess</a> subsections.</p></li><li><p>Added a <a href="https://fmhy.net/internet-tools#firefox-tools" target="_blank" rel="noreferrer">Firefox Tools</a> section to Internet.</p></li><li><p>Added a <a href="https://fmhy.net/privacy#data-breach-monitoring" target="_blank" rel="noreferrer">Data Breach Monitoring</a> section to Privacy.</p></li><li><p>Added a <a href="https://fmhy.net/system-tools#task-automation" target="_blank" rel="noreferrer">Task Automation</a> section to System Tools.</p></li><li><p>Added a <a href="https://fmhy.net/linux-macos#unix-like" target="_blank" rel="noreferrer">Unix-Like</a> section to the bottom of Linux.</p></li><li><p>Added Size Limits + Sign-up Requirements to <a href="https://fmhy.net/torrenting#remote-torrenting" target="_blank" rel="noreferrer">Remote Torrenting</a> descriptions.</p></li><li><p>Re-organized <a href="https://fmhy.net/mobile#android-audio-players" target="_blank" rel="noreferrer">Android Audio Players</a> based on <a href="https://i.imgur.com/2FOFOth.png" target="_blank" rel="noreferrer">Poll Results</a>. The four stars are now: Poweramp, Musicolet, VLC, and foobar2000.</p></li><li><p>Re-organized <a href="https://fmhy.net/mobile#keyboard-tools" target="_blank" rel="noreferrer">Android Keyboards</a> based on <a href="https://i.imgur.com/OE8zsC0.png" target="_blank" rel="noreferrer">Poll Results</a>. FUTO managed to keep its top spot, and Heli was bumped up much higher.</p></li><li><p>Re-organized <a href="https://fmhy.net/video#live-sports" target="_blank" rel="noreferrer">Live Sports</a>, removed sites w/ broken or dupe players, and starred a few that seemed to stand out. <a href="https://i.imgur.com/eDioF9L.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Re-organized <a href="https://fmhy.net/audio#radio-streaming" target="_blank" rel="noreferrer">Radio Streaming</a> + <a href="https://fmhy.net/audio#internet-radio" target="_blank" rel="noreferrer">Internet Radio</a>, added new stars and new labels, and moved both sections out of storage.</p></li><li><p>Re-organized <a href="https://fmhy.net/internet-tools#rss-readers" target="_blank" rel="noreferrer">RSS Readers</a>, improved labels, and removed bad ones. <a href="https://i.imgur.com/oAVEC6H.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Re-organized <a href="https://fmhy.net/gaming#text-adventures" target="_blank" rel="noreferrer">Text Adventures</a>, added labels, and moved out of storage. <a href="https://i.imgur.com/JrdEDC3.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Re-organized Dev Tool Sites, moved out of storage, and separated into <a href="https://fmhy.net/developer-tools#dev-tool-indexes" target="_blank" rel="noreferrer">Indexes</a> + <a href="https://fmhy.net/developer-tools#online-toolkits" target="_blank" rel="noreferrer">Online Toolkits</a>. <a href="https://i.imgur.com/JyJOW9v.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li><li><p>Updated <a href="https://github.com/fmhy/FMHY/wiki/Stream-Site-Grading" target="_blank" rel="noreferrer">grading criteria #4 and #5</a> to reward sites that have source auto-switch + episode auto-next working across all their servers. Also merged quality, subtitle, and media type criteria into #1 to simplify scoring, and started giving points for watch party support. This has reduced the total amount of stars and helped the best sites stand out more. <a href="https://i.imgur.com/omYr1pQ.png" target="_blank" rel="noreferrer">Before vs. After</a>.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/ai#image-generation" target="_blank" rel="noreferrer">LMArena</a> in Image Gen. Good models, unlimited, no sign-up required; clear cookies if you&#39;re getting errors.</p></li><li><p>Starred <a href="https://fmhy.net/ai#online-chatbots" target="_blank" rel="noreferrer">HuggingChat</a> in Online Chatbots. Privacy-friendly, lots of models, sign-up required, but temp-mail works.</p></li><li><p>Starred <a href="https://fmhy.net/file-tools#file-transfer" target="_blank" rel="noreferrer">Blip</a> in File Transfer. Easily transfer large files over the internet or between your own devices. Well-liked by everyone in our Discord who has tried it.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#camera-tools" target="_blank" rel="noreferrer">ImageToolbox</a> in Android Image Editors. Open-source, feature-rich, and well-maintained.</p></li><li><p>Starred <a href="https://fmhy.net/social-media-tools#youtube-downloaders" target="_blank" rel="noreferrer">Parabolic</a> in YouTube Downloaders. Open-source, multi-platform, and one of the easier-to-use yt-dlp frontends.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#tracking-databases" target="_blank" rel="noreferrer">Infinite Backlog</a> in Game Tracking / Databases. Backloggd/Glitchwave competitor with a nice UI, achievement integration, and challenges.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#game-mods" target="_blank" rel="noreferrer">GameBanana</a> in Game Mods. High-quality, well-organized, and the go-to for certain franchises like Sonic, Celeste, etc.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#party-multiplayer" target="_blank" rel="noreferrer">TETR.IO</a> in Multiplayer Browser Games. F2P multiplayer Tetris that&#39;s popular, feature-rich, and <a href="https://tetr.io/about/patchnotes/" target="_blank" rel="noreferrer">well-maintained</a> by its devs.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#browser-games" target="_blank" rel="noreferrer">Mario Kart PC</a> in Browser Games. SNES-style Mario Kart w/ <a href="https://mkpc.malahieude.net/creations.php" target="_blank" rel="noreferrer">Custom Maps</a> &amp; Multiplayer.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-audio" target="_blank" rel="noreferrer">RootlessJamesDSP</a> in Android Audio Equalizers. Open-source, supports many apps, AutoEQ support; good Poweramp alt.</p></li><li><p>Starred <a href="https://fmhy.net/gaming#geoguessr-games" target="_blank" rel="noreferrer">Plonk It</a> in GeoGuessr Games. Active community for learning GeoGuessr.</p></li><li><p>Starred <a href="https://fmhy.net/ai#coding-ais" target="_blank" rel="noreferrer">Zed</a> in Coding AIs. Collaborative coding AI getting positive attention from <a href="https://news.ycombinator.com/item?id=43959710" target="_blank" rel="noreferrer">HackerNews</a> + our members.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li>Unstarred OOMoye as their library seems a lot smaller now, and their search is still broken.</li></ul>',9))])}const b=t(l,[["render",d]]);export{c as __pageData,b as default};
